import{_ as i,C as a,o as r,c as o,ag as s,E as d}from"./chunks/framework.cyF4XceO.js";const k=JSON.parse('{"title":"Versions and compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"docs/versions.md","filePath":"docs/versions.md"}'),n={name:"docs/versions.md"};function l(c,e,h,m,p,u){const t=a("StatusNote");return r(),o("div",null,[e[0]||(e[0]=s(`<h1 id="versions-and-compatibility" tabindex="-1">Versions and compatibility <a class="header-anchor" href="#versions-and-compatibility" aria-label="Permalink to &quot;Versions and compatibility&quot;">​</a></h1><p>Takoform keeps five independent axes: Provider, Host API, Form Family, Form definition, and Form Package API/status. A version on one axis is not a pre-release label for another axis.</p><h2 id="current-design-target" tabindex="-1">Current design target <a class="header-anchor" href="#current-design-target" aria-label="Permalink to &quot;Current design target&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Axis</th><th>Current identity</th><th>Meaning and availability</th></tr></thead><tbody><tr><td>Provider</td><td><strong>Provider 2.1.1</strong></td><td>Registry-published stable client distribution. The repository descriptor remains <code>candidate-only</code> metadata by design after owner publication.</td></tr><tr><td>Host API</td><td><strong>Host API v1beta1</strong></td><td>Beta protocol: discovery, exact Form availability, operations, fencing, and errors.</td></tr><tr><td>Form Family</td><td><strong>Edge Form Family v1beta1</strong></td><td>Beta family containing the current 15 Experimental Form definitions.</td></tr><tr><td>Form definition</td><td><strong>definition 0.1.0</strong></td><td>The exact definition version used by each of the 15 current Experimental Forms.</td></tr><tr><td>Form Package envelope</td><td><strong><code>packages.forms.takoform.com/v1alpha4</code></strong></td><td>Separate package/distribution schema identifier. Package artifacts remain unpublished.</td></tr></tbody></table><p>Provider distribution is a separate axis. <strong>Provider 2.1.1</strong> is the current Registry-readback client, <strong>Provider 2.0.0</strong> is the published compatibility predecessor for the retained surface, and <strong>Provider 1.0.3</strong> remains the published Legacy client for existing v1 state.</p><h2 id="published-compatibility-mapping" tabindex="-1">Published compatibility mapping <a class="header-anchor" href="#published-compatibility-mapping" aria-label="Permalink to &quot;Published compatibility mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Client or distribution</th><th>Host API</th><th>Forms and definitions</th><th>Status / use</th></tr></thead><tbody><tr><td>Provider 2.1.1 distribution</td><td>Host API v1beta1</td><td>Edge Form Family v1beta1; 15 Experimental Forms at definition 0.1.0</td><td>Registry-published current client; descriptor remains <code>candidate-only</code> metadata by design.</td></tr><tr><td>Provider 2.0.0 distribution</td><td>Host API v1alpha2</td><td>Retained provider-v2 Forms at their retained definition identities</td><td>Registry-published compatibility client.</td></tr><tr><td>Provider 1.0.3 Legacy</td><td>Host API v1alpha1</td><td>The immutable v1 Form Package identities</td><td>Registry-published migration and recovery client.</td></tr></tbody></table><p>The host API and Form family are not interchangeable labels: Host API v1beta1 is the wire protocol, while Edge Form Family v1beta1 names the group of Forms that use it. Likewise, definition 0.1.0 is a Form identity and does not change the Provider 2.1.1 SemVer.</p><h2 id="current-design-target-—-edge-form-family-v1beta1-15-experimental-forms" tabindex="-1">Current design target — Edge Form Family v1beta1 (15 Experimental Forms) <a class="header-anchor" href="#current-design-target-—-edge-form-family-v1beta1-15-experimental-forms" aria-label="Permalink to &quot;Current design target — Edge Form Family v1beta1 (15 Experimental Forms)&quot;">​</a></h2><p>The current stack is the Host API v1beta1 plus these 15 typed resources. Every resource is an Experimental Form with definition 0.1.0:</p><ul><li><a href="/docs/resources/module_worker.html"><code>takoform_module_worker</code></a></li><li><a href="/docs/resources/worker_bundle.html"><code>takoform_worker_bundle</code></a></li><li><a href="/docs/resources/static_asset_bundle.html"><code>takoform_static_asset_bundle</code></a></li><li><a href="/docs/resources/worker_version.html"><code>takoform_worker_version</code></a></li><li><a href="/docs/resources/worker_deployment.html"><code>takoform_worker_deployment</code></a></li><li><a href="/docs/resources/worker_custom_domain.html"><code>takoform_worker_custom_domain</code></a></li><li><a href="/docs/resources/worker_endpoint.html"><code>takoform_worker_endpoint</code></a></li><li><a href="/docs/resources/worker_cron_trigger.html"><code>takoform_worker_cron_trigger</code></a></li><li><a href="/docs/resources/edge_kv_namespace.html"><code>takoform_edge_kv_namespace</code></a></li><li><a href="/docs/resources/edge_object_bucket.html"><code>takoform_edge_object_bucket</code></a></li><li><a href="/docs/resources/sqlite_database.html"><code>takoform_sqlite_database</code></a></li><li><a href="/docs/resources/sqlite_migration_set.html"><code>takoform_sqlite_migration_set</code></a></li><li><a href="/docs/resources/sqlite_migration_application.html"><code>takoform_sqlite_migration_application</code></a></li><li><a href="/docs/resources/at_least_once_queue.html"><code>takoform_at_least_once_queue</code></a></li><li><a href="/docs/resources/queue_consumer.html"><code>takoform_queue_consumer</code></a></li></ul><p>The current target is actionable from the Registry:</p><div class="language-hcl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hcl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">terraform</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  required_providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    takoform</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      source  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;registry.terraform.io/tako0614/takoform&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      version </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;= 2.1.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The repository descriptor remains <code>candidate-only</code> metadata by design after owner publication; that metadata does not revoke the Registry client.</p><h2 id="published-compatibility-migration-history" tabindex="-1">Published compatibility / Migration / History <a class="header-anchor" href="#published-compatibility-migration-history" aria-label="Permalink to &quot;Published compatibility / Migration / History&quot;">​</a></h2><details><summary>Retained Provider 2.0.0 and Legacy Provider 1.0.3</summary><h3 id="provider-2-0-0" tabindex="-1">Provider 2.0.0 / Host API v1alpha2 <a class="header-anchor" href="#provider-2-0-0" aria-label="Permalink to &quot;Provider 2.0.0 / Host API v1alpha2 {#provider-2-0-0}&quot;">​</a></h3><p>The retained provider-v2 surface remains reachable through the existing resource URLs. These nine resources are kept as compatibility history, not as the current Edge Form Family:</p><ul><li><a href="/docs/resources/edge_worker.html"><code>takoform_edge_worker</code></a></li><li><a href="/docs/resources/relational_database.html"><code>takoform_relational_database</code></a></li><li><a href="/docs/resources/object_bucket.html"><code>takoform_object_bucket</code></a></li><li><a href="/docs/resources/key_value_store.html"><code>takoform_key_value_store</code></a></li><li><a href="/docs/resources/queue.html"><code>takoform_queue</code></a></li><li><a href="/docs/resources/schedule.html"><code>takoform_schedule</code></a></li><li><a href="/docs/resources/container_service.html"><code>takoform_container_service</code></a></li><li><a href="/docs/resources/stateful_entity.html"><code>takoform_stateful_entity</code></a></li><li><a href="/docs/resources/vector_index.html"><code>takoform_vector_index</code></a></li><li><a href="/docs/data-sources/interface.html">Interface data source</a></li></ul><p>Provider 2.0.0 discovers exact retained FormRefs at <code>/.well-known/takoform/v1alpha2</code>. The retained package index is <code>packages.forms.takoform.com/v1alpha3</code>; neither identity is silently remapped to the current v1beta1 stack.</p><h3 id="provider-1-0-3" tabindex="-1">Provider 1.0.3 / Host API v1alpha1 <a class="header-anchor" href="#provider-1-0-3" aria-label="Permalink to &quot;Provider 1.0.3 / Host API v1alpha1 {#provider-1-0-3}&quot;">​</a></h3><p>Provider 1.0.3 remains the immutable Legacy client. Keep it pinned for existing v1 state, refresh/delete/recovery, and any migration step that still needs the v1 wire. Its discovery boundary is <code>/.well-known/takoform/v1alpha1</code>, and the published v1 Form Package identities remain historical evidence.</p><h3 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h3><p>Migration is explicit rather than an automatic state rewrite:</p><ol><li>Pin Provider 1.0.3 and refresh the Legacy resource.</li><li>Record non-secret desired configuration and required public outputs.</li><li>Create under an exact Host API v1alpha2 FormRef, or import only with host conformance proof, using Provider 2.0.0.</li><li>Move consumers, observe the result, and delete Legacy only after rollback is no longer needed.</li></ol><p>See the <a href="/release/migrations/v1-to-v2.html">Provider 1 to 2 migration guide</a> for the operational sequence. Published identities are immutable: compatibility means retaining the old URL and meaning, not relabeling it as v1beta1.</p></details>`,16)),d(t)])}const b=i(n,[["render",l]]);export{k as __pageData,b as default};
